import json, os
H = os.path.dirname(os.path.abspath(__file__))

def S(year, label, title, text, terr, fronts, moves, events):
    return {"year": year, "label": label, "title": title, "text": text,
            "territories": [{"side": s, "polities": p} for s, p in terr],
            "fronts": fronts, "moves": moves, "events": events}
def M(side, cmd, label, path): return {"side": side, "commander": cmd, "label": label, "path": path}
def E(name, kind, lon, lat, year, winner, text):
    return {"name": name, "kind": kind, "lon": lon, "lat": lat, "year": year, "winner": winner, "text": text}
def F(path, label): return {"path": path, "label": label}
def T(lon, lat, r): return {"lon": lon, "lat": lat, "r": r}

